import{ax as s,A as e,aQ as n,z as p}from"./chunks/framework.BWRXlwpK.js";const k=JSON.parse('{"title":"Network 网络","description":"","frontmatter":{},"headers":[],"relativePath":"docker/docker-network.md","filePath":"docker/docker-network.md","lastUpdated":1788144574000}'),t={name:"docker/docker-network.md"};function i(o,a,l,c,d,r){return p(),e("div",null,a[0]||(a[0]=[n(`<h1 id="network-网络" tabindex="-1">Network 网络 <a class="header-anchor" href="#network-网络" aria-label="Permalink to &quot;Network 网络&quot;">​</a></h1><blockquote><p>Network（网络）解决的是容器之前的通信问题。</p></blockquote><p>假设我们有两个容器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spring Boot</span></span>
<span class="line"><span>Node.js</span></span></code></pre></div><p>在没有 Docker 时，它是这样运行的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spring Boot</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>localhost:3306</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>MySQL</span></span></code></pre></div><p>因为他们都运行在一台机器上，所以 java 在访问 MySql 时没有问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring.datasource.url=jdbc:mysql://localhost:3306/demo</span></span></code></pre></div><p>但是在使用 Docker 后</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Container A</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Spring Boot</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Container B</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MySQL</span></span></code></pre></div><p>现在两个服务在不同的 Container 中，那么显然就无法直接连接了。</p><p>因为在单个 ContainerA 中，localhost 不是宿主机、不是MySQL，而是 ContainerA 本身，它无法超出自身。</p><p>所以</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jdbc:mysql://localhost:3306/demo</span></span></code></pre></div><p>连接的是 ContainerA 自己，而它自己又没有数据库，因此导致失败。</p><p>针对上述问题，Docker提供了Network来解决。</p><h2 id="network-连接" tabindex="-1">Network 连接 <a class="header-anchor" href="#network-连接" aria-label="Permalink to &quot;Network 连接&quot;">​</a></h2><p>创建一个网络 <code>demo-network</code>，然后把两个 Container 放进去。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>demo-network</span></span>
<span class="line"><span></span></span>
<span class="line"><span>├── springboot</span></span>
<span class="line"><span>└── mysql</span></span></code></pre></div><p>这时候 Docker 自动提供 DNS，于是Spring Boot 可以直接连接 Mysql。</p><p>以前：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring.datasource.url=jdbc:mysql://localhost:3306/demo</span></span></code></pre></div><p>现在：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring.datasource.url=jdbc:mysql://mysql:3306/demo</span></span></code></pre></div><p>这里 mysql 就是 Container 的名字（Container B）。</p><p>Docker 将自动解析 IP。</p><h2 id="为什么不用ip" tabindex="-1">为什么不用IP？ <a class="header-anchor" href="#为什么不用ip" aria-label="Permalink to &quot;为什么不用IP？&quot;">​</a></h2><p>因为IP可能会改变，为了不每次都要检查IP，所以才使用自动解析的方式。</p><h2 id="宿主机如何访问-container-中的服务" tabindex="-1">宿主机如何访问 Container 中的服务？ <a class="header-anchor" href="#宿主机如何访问-container-中的服务" aria-label="Permalink to &quot;宿主机如何访问 Container 中的服务？&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3307:3306</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span></span></code></pre></div><p>以MySQL为例，通过 <code>-p</code> 命令可以映射端口，从而让宿主机访问到 MySQL。</p><ul><li>3307：宿主机的端口</li><li>3306：容器的端口</li></ul><p>因为要防止端口冲突，所以采用这种方式进行映射。</p><p>在宿主机可以直接通过 <code>localhost:3307</code> 访问到 MySQL。</p>`,35)]))}const g=s(t,[["render",i]]);export{k as __pageData,g as default};
